@ExtendWith(MockitoExtension.class)          // STRICT_STUBS mặc định
class OrderServiceTest {
    @Mock OrderRepository repo;
    OrderService service;

    @BeforeEach
    void setUp() { service = new OrderService(repo); }

    @Test
    void cannotCancelShippedOrder() {
        Order shipped = new Order(42L, Status.SHIPPED);
        when(repo.findByIdForUpdate(42L)).thenReturn(Optional.of(shipped));

        CannotCancelException error =
                assertThrows(CannotCancelException.class, () -> service.cancel(42L));

        assertEquals("order 42 already shipped", error.getMessage());
        assertEquals(Status.SHIPPED, shipped.status);
        verify(repo, never()).save(any());
    }
}

